import { HttpErrorResponse } from '@angular/common/http';
import { Component, inject, input, output, signal } from '@angular/core';
import { AMOUNT, CLAIM_NUMBER, ClaimAction, ClaimView, ClaimsApi, cents, dueBy, money, overdue, roundsHalfUp } from '../../core/claims';
import { GradeView, gradeOn } from '../../core/people';
import { PeriodView, periodOn } from '../../core/periods';
import { NO_RATE, RateView, claimDueCents } from '../../core/rates';
import { Session } from '../../core/session';

// A person's claims: listed newest first, added and edited through one form on the person's row,
// and moved through their statuses (open, settle, approve, reject with a reason, void) from each
// claim's row.
const PAST: Record<ClaimAction, string> = {
  open: 'opened',
  settle: 'settled',
  approve: 'approved',
  reject: 'rejected',
  void: 'voided',
};

@Component({
  selector: 'app-claims',
  template: `
    <form (submit)="save($event)" [attr.aria-label]="(editing() === null ? 'Add a claim for ' : 'Edit a claim of ') + personName()">
      <label [for]="'claim-form-amount-' + personId()">Amount</label>
      <input
        [id]="'claim-form-amount-' + personId()"
        data-testid="claim-form-amount"
        inputmode="decimal"
        [value]="amount()"
        (input)="amount.set(value($event)); error.set(null)"
      />
      <label [for]="'claim-form-date-' + personId()">Date</label>
      <input
        [id]="'claim-form-date-' + personId()"
        type="date"
        data-testid="claim-form-date"
        [value]="date()"
        (input)="date.set(value($event)); error.set(null)"
      />
      <label [for]="'claim-form-note-' + personId()">Note</label>
      <input
        [id]="'claim-form-note-' + personId()"
        data-testid="claim-form-note"
        [value]="note()"
        (input)="note.set(value($event)); error.set(null)"
      />
      <label [for]="'claim-form-corrects-' + personId()">Corrects claim no.</label>
      <input
        [id]="'claim-form-corrects-' + personId()"
        data-testid="claim-form-corrects"
        inputmode="numeric"
        [value]="corrects()"
        (input)="corrects.set(value($event)); error.set(null)"
      />
      <button type="submit" data-testid="claim-form-submit">
        {{ editing() === null ? 'Add claim' : 'Save claim' }}
      </button>
      @if (editing() !== null) {
        <button type="button" data-testid="claim-form-cancel" (click)="reset()">Cancel</button>
      }
      @if (error(); as message) {
        <p role="alert" data-testid="claim-form-error">{{ message }}</p>
      }
    </form>
    <ul [attr.aria-label]="'Claims of ' + personName()">
      @for (c of claims(); track c.id) {
        <li [attr.data-testid]="'claim-row-' + c.id">
          <input
            type="checkbox"
            data-testid="claim-select"
            [attr.aria-label]="'Select claim of ' + c.amount + ' on ' + c.date"
            [checked]="selected().has(c.id)"
            (change)="selectedChange.emit({ id: c.id, on: checked($event) })"
          />
          <span>No. <span data-testid="claim-number">{{ c.number ?? '' }}</span></span>
          <span data-testid="claim-amount">{{ c.amount }}</span>
          <span data-testid="claim-date">{{ c.date }}</span>
          <span data-testid="claim-note">{{ c.note }}</span>
          <span>Due <span data-testid="claim-due">{{ dueOf(c) }}</span></span>
          <span>Due by <span data-testid="claim-due-by">{{ dueByOf(c) }}</span></span>
          <span>Overdue <span data-testid="claim-overdue">{{ overdueOf(c) ? 'yes' : 'no' }}</span></span>
          <span>Period <span data-testid="claim-period">{{ periodOf(c) }}</span></span>
          <span data-testid="claim-status">{{ c.status }}</span>
          <span>Stated <span data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</span></span>
          <span>Corrects <span data-testid="claim-corrects">{{ c.corrects ?? '' }}</span></span>
          <span>Opened by <span data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</span></span>
          <button
            type="button"
            data-testid="claim-edit"
            [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date"
            (click)="open(c)"
          >
            Edit
          </button>
          <label [for]="'claim-reject-reason-' + c.id">Reject reason</label>
          <input
            [id]="'claim-reject-reason-' + c.id"
            data-testid="claim-reject-reason"
            [value]="rejectReasons()[c.id] ?? ''"
            (input)="setRejectReason(c.id, value($event))"
          />
          @for (a of actions; track a.action) {
            <button
              type="button"
              [attr.data-testid]="'claim-' + a.action"
              [attr.aria-label]="a.label + ' claim of ' + c.amount + ' on ' + c.date"
              (click)="act(c, a.action)"
            >
              {{ a.label }}
            </button>
          }
          @if (claimError()?.id === c.id) {
            <p role="alert" data-testid="claim-error">{{ claimError()?.message }}</p>
          }
        </li>
      }
    </ul>
  `,
})
export class Claims {
  private readonly session = inject(Session);
  private readonly api = inject(ClaimsApi);

  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  /** The person's claims, newest first. */
  readonly claims = input.required<ClaimView[]>();
  /** The person's grades by the date each is in force from; each claim uses the one on its date. */
  readonly grades = input.required<GradeView[]>();
  /** The sheet's rates; each claim uses the one its person's grade has in force on its date. */
  readonly rates = input.required<RateView[]>();
  /** The sheet's periods; each claim belongs to the one whose dates contain its date, or to none. */
  readonly periods = input.required<PeriodView[]>();
  /** The ids of the claims selected for a bulk action. */
  readonly selected = input.required<ReadonlySet<number>>();
  /** A claim's checkbox ticked (on) or cleared. */
  readonly selectedChange = output<{ id: number; on: boolean }>();
  /** A claim added or saved through the form. */
  readonly saved = output<ClaimView>();

  protected readonly amount = signal('');
  protected readonly date = signal('');
  protected readonly note = signal('');
  /** The number of the SETTLED claim a correction corrects; empty on any other claim. */
  protected readonly corrects = signal('');
  /** The id of the claim open in the form, or null when the form adds a new claim. */
  protected readonly editing = signal<number | null>(null);
  protected readonly error = signal<string | null>(null);
  /** A submit is waiting for its answer: a second submit meanwhile is ignored. */
  private busy = false;
  /** The refusal of the last action taken on a claim's row, shown on that row. */
  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
  protected readonly actions: { action: ClaimAction; label: string }[] = [
    { action: 'open', label: 'Open' },
    { action: 'settle', label: 'Settle' },
    { action: 'approve', label: 'Approve' },
    { action: 'reject', label: 'Reject' },
    { action: 'void', label: 'Void' },
  ];
  /** The reason typed on each claim's row for rejecting it, by claim id. */
  protected readonly rejectReasons = signal<Record<number, string>>({});

  /**
   * What is due on a claim: the due fixed when it was settled, or else the figure its person's last
   * statement bound it to, or else its amount at the rate the
   * person's grade has in force on the claim's date (n/a when it is dated before every rate), with
   * its late charge on top while it is overdue.
   */
  protected dueOf(claim: ClaimView): string {
    const late = { pct: this.session.latePct(), terms: this.session.terms(), today: this.session.today() ?? '' };
    const halfUp = roundsHalfUp(claim, this.claims(), this.session.policyDate(), late.today);
    const figure = claimDueCents(claim, this.rates(), gradeOn(this.grades(), claim.date), cents(this.session.floor()), late, halfUp);
    return figure === null ? NO_RATE : money(figure);
  }

  /** A claim's due-by: its date plus the sheet's terms. */
  protected dueByOf(claim: ClaimView): string {
    return dueBy(claim, this.session.terms());
  }

  /** Whether a claim is OPEN and due by a date before the sheet's today. */
  protected overdueOf(claim: ClaimView): boolean {
    return overdue(claim, this.session.terms(), this.session.today() ?? '');
  }

  /** The name of the period a claim's date falls in; empty when it falls in none. */
  protected periodOf(claim: ClaimView): string {
    return periodOn(this.periods(), claim.date)?.name ?? '';
  }

  protected checked(event: Event): boolean {
    return (event.target as HTMLInputElement).checked;
  }

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  /**
   * Open a claim's editor: the form takes its values. Only a DRAFT claim can be edited; any other is
   * refused with an error on its row (to change an OPEN claim, void it and add a new one), as is one
   * dated in a closed period.
   */
  protected open(claim: ClaimView): void {
    this.claimError.set(null);
    if (claim.status !== 'DRAFT') {
      this.reset();
      this.claimError.set({
        id: claim.id,
        message: `A ${claim.status} claim cannot be edited; void it and add a new one.`,
      });
      return;
    }
    const period = periodOn(this.periods(), claim.date);
    if (period?.closed) {
      this.reset();
      this.claimError.set({ id: claim.id, message: `Period ${period.name} is closed, so its claims cannot be edited.` });
      return;
    }
    this.editing.set(claim.id);
    this.amount.set(claim.amount);
    this.date.set(claim.date);
    this.note.set(claim.note);
    this.corrects.set(claim.corrects ?? '');
    this.error.set(null);
  }

  /** Type the reason for rejecting a claim; it clears any error left on the claim's row. */
  protected setRejectReason(id: number, reason: string): void {
    this.rejectReasons.update((reasons) => ({ ...reasons, [id]: reason }));
    if (this.claimError()?.id === id) this.claimError.set(null);
  }

  /**
   * Move a claim's status; a move its status does not allow is refused with an error on its row, as
   * is a reject without a reason. A clerk settling a claim above the clerk limit sends it PENDING.
   */
  protected async act(claim: ClaimView, action: ClaimAction): Promise<void> {
    this.claimError.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const reason = (this.rejectReasons()[claim.id] ?? '').trim();
    if (action === 'reject' && reason === '') {
      this.claimError.set({ id: claim.id, message: 'Type a reason to reject the claim.' });
      return;
    }
    try {
      this.saved.emit(await this.api.act(sheet, claim.id, action, reason));
      if (action === 'reject') this.rejectReasons.update((reasons) => ({ ...reasons, [claim.id]: '' }));
    } catch (e) {
      const mine = claim.openedBy === this.session.user()?.trim();
      const own = (action === 'settle' && claim.status === 'OPEN' && mine)
        || (action === 'approve' && claim.status === 'PENDING' && mine);
      const steward = (action === 'approve' || action === 'reject') && claim.status === 'PENDING'
        && e instanceof HttpErrorResponse && e.status === 403;
      this.claimError.set({
        id: claim.id,
        message: own
          ? `You opened this claim, so someone else must ${action} it.`
          : steward
            ? `Only a steward can ${action} a PENDING claim.`
            : `A ${claim.status} claim cannot be ${PAST[action]}.`,
      });
    }
  }

  protected reset(): void {
    this.editing.set(null);
    this.amount.set('');
    this.date.set('');
    this.note.set('');
    this.corrects.set('');
    this.error.set(null);
  }

  protected async save(event: Event): Promise<void> {
    event.preventDefault();
    if (this.busy) return;
    this.error.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const amount = this.amount().trim();
    if (!AMOUNT.test(amount)) {
      this.error.set('Type an amount with up to two decimals; below 0.00 only for a correction.');
      return;
    }
    const corrects = this.corrects().trim();
    if (corrects !== '' && !CLAIM_NUMBER.test(corrects)) {
      this.error.set('Type the number of the claim it corrects.');
      return;
    }
    const form = { amount, date: this.date().trim() || null, note: this.note(), corrects: corrects === '' ? null : corrects };
    const id = this.editing();
    this.busy = true;
    try {
      const claim = id === null
        ? await this.api.add(sheet, this.personId(), form)
        : await this.api.edit(sheet, id, form);
      this.saved.emit(claim);
      this.reset();
    } catch {
      const verb = id === null ? 'added' : 'saved';
      this.error.set(amount.startsWith('-') || corrects !== ''
        ? `The claim could not be ${verb}: a correction (an amount below 0.00) must name a SETTLED claim of ${this.personName()}, and only a correction names one.`
        : `The claim could not be ${verb}.`);
    } finally {
      this.busy = false;
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/**
 * DRAFT when added; DRAFT → OPEN → SETTLED, and DRAFT, OPEN or PENDING → VOID. A clerk settling a claim
 * above the clerk limit sends it PENDING; a steward approves it (SETTLED) or rejects it (OPEN again).
 */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A move of a claim's status: open, settle, approve, reject or void. */
export type ClaimAction = 'open' | 'settle' | 'approve' | 'reject' | 'void';

/** Whether a claim is open: OPEN, or PENDING a steward's approval. */
export function isOpen(claim: ClaimView): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

export interface ClaimView {
  id: number;
  personId: number;
  /** The amount with two decimals, e.g. "10.25". */
  amount: string;
  /** yyyy-mm-dd */
  date: string;
  note: string;
  status: ClaimStatus;
  /**
   * The number given when the claim was opened: sheet-wide (e.g. "3"), or under period numbering
   * within its period (e.g. "P1-2", or "X-1" in no period); null while DRAFT, and kept once VOID.
   */
  number: string | null;
  /**
   * The due fixed when the claim was settled, with two decimals; null when it is not fixed (not
   * settled, or the grade had no rate then), so its due follows the current rate.
   */
  settledDue: string | null;
  /** The user who opened the claim; null until it is opened. The opener cannot settle it. */
  openedBy: string | null;
  /** Whether the claim is bound by its person's last statement to the figure it had then. */
  stated: boolean;
  /** The figure the statement bound the claim to, with two decimals; null when unbound, or when it was n/a. */
  statedDue: string | null;
  /** The number of the SETTLED claim this one corrects; null unless it is a correction. */
  corrects: string | null;
}

/** Whether a claim is a correction: its amount is below 0.00. It has no floor and no late charge. */
export function isCorrection(claim: ClaimView): boolean {
  return claim.amount.startsWith('-') && cents(claim.amount) !== 0;
}

/** Whether a claim counts toward what is claimed and due: only OPEN, PENDING and SETTLED claims do. */
export function counts(claim: ClaimView): boolean {
  return isOpen(claim) || claim.status === 'SETTLED';
}

/** A claim's due-by (yyyy-mm-dd): its date plus the sheet's terms in days. */
export function dueBy(claim: ClaimView, terms: number): string {
  const [y, m, d] = claim.date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is OPEN or PENDING and its due-by is before the sheet's today. */
export function overdue(claim: ClaimView, terms: number, today: string): boolean {
  return isOpen(claim) && today !== '' && dueBy(claim, terms) < today;
}

/** What a late charge is worked from: the sheet's late percent, terms and today. */
export interface LateTerms {
  /** The late percent with two decimals. */
  pct: string;
  terms: number;
  /** The sheet's today (yyyy-mm-dd); empty when none is loaded. */
  today: string;
}

/**
 * Whether a claim's live figures round half up (else half to even): when the date it rounds by is
 * before the policy date, or the sheet's today when no policy date is set. A correction rounds by the
 * date of the claim it corrects, found by number among its person's claims (its own when not found).
 */
export function roundsHalfUp(claim: ClaimView, claims: ClaimView[], policyDate: string, today: string): boolean {
  const corrected = claim.corrects === null
    ? undefined
    : claims.find((c) => c.personId === claim.personId && c.number === claim.corrects);
  const date = corrected?.date ?? claim.date;
  const policy = policyDate || today;
  return policy !== '' && date < policy;
}

/** How many full 30 days an overdue claim is past its due-by on the sheet's today; 0 when not overdue. */
export function latePeriods(claim: ClaimView, late: LateTerms): number {
  if (!overdue(claim, late.terms, late.today)) return 0;
  const days = (Date.parse(late.today) - Date.parse(dueBy(claim, late.terms))) / 86_400_000;
  return Math.floor(days / 30);
}

/** What a bulk open did: the claims opened, as they are now, and how many were refused. */
export interface BulkOpenView {
  opened: ClaimView[];
  refused: number;
}

export interface ClaimForm {
  amount: string;
  /** Empty means the sheet's today (or, on an edit, the claim's own date). */
  date: string | null;
  note: string;
  /** The number of the claim a correction corrects; null on any other claim. */
  corrects: string | null;
}

/** An amount as a claim takes it: up to two decimals, below 0.00 only on a correction. */
export const AMOUNT = /^-?\d{1,12}(\.\d{1,2})?$/;

/** A claim number as the form takes it: sheet-wide (e.g. "3") or within a period (e.g. "P1-2", "X-1"). */
export const CLAIM_NUMBER = /^([1-9]\d{0,8}|\S.{0,200}-[1-9]\d{0,8})$/;

/** A two-decimal amount in whole cents, so sums are exact. */
export function cents(amount: string): number {
  const negative = amount.startsWith('-');
  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
  const abs = Number(whole) * 100 + Number(frac.padEnd(2, '0'));
  return negative ? -abs : abs;
}

/** Whole cents shown with two decimals. */
export function money(cents: number): string {
  const abs = Math.abs(cents);
  return `${cents < 0 ? '-' : ''}${Math.trunc(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}

// The claims people on a sheet make, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class ClaimsApi {
  private readonly http = inject(HttpClient);

  /** The sheet's claims, newest first. */
  list(sheet: string): Promise<ClaimView[]> {
    return firstValueFrom(this.http.get<ClaimView[]>(`${this.url(sheet)}/claims`));
  }

  add(sheet: string, personId: number, form: ClaimForm): Promise<ClaimView> {
    return firstValueFrom(this.http.post<ClaimView>(`${this.url(sheet)}/people/${personId}/claims`, form));
  }

  edit(sheet: string, id: number, form: ClaimForm): Promise<ClaimView> {
    return firstValueFrom(this.http.put<ClaimView>(`${this.url(sheet)}/claims/${id}`, form));
  }

  /**
   * Move a claim's status; refused (409) when its status does not allow the move, or when the user
   * settling or approving it is the one who opened it, and (403) when approving or rejecting it is
   * not a steward. A reject carries its reason.
   */
  act(sheet: string, id: number, action: ClaimAction, reason?: string): Promise<ClaimView> {
    const body = action === 'reject' ? { reason: reason ?? '' } : null;
    return firstValueFrom(this.http.post<ClaimView>(`${this.url(sheet)}/claims/${id}/${action}`, body));
  }

  /**
   * Open the selected claims together, in list order (people in the order they were added, each
   * person's claims newest first); those that cannot be opened are refused and left as they are.
   */
  openAll(sheet: string, claimIds: number[]): Promise<BulkOpenView> {
    return firstValueFrom(this.http.post<BulkOpenView>(`${this.url(sheet)}/claims/open`, { claimIds }));
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}`;
  }
}

